// Example of proper input validation using express-validator
const { body, validationResult } = require('express-validator');

// Example validation middleware for user endpoints
const validateUserInput = [
  body('email').isEmail().normalizeEmail(),
  body('name').trim().isLength({ min: 1, max: 100 }).escape(),
  body('id').isInt({ min: 1 }).toInt()
];

app.use(express.json({ limit: '10kb' })); // Limit JSON payload size

// Protected endpoint example
app.get('/users/:id', validateUserInput, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process request
});

// Example authentication middleware using JWT or sessions
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(apiLimiter);

// JWT authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// Protect sensitive endpoints
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([...]);
});

// Security middleware
const helmet = require('helmet');
const cors = require('cors');

// Use helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  crossOriginEmbedderPolicy: false,
}));

// Configure CORS properly
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Environment configuration security
require('dotenv').config(); // Load .env files

const crypto = require('crypto');

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    console.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

// Generate secure secrets if not provided
if (!process.env.JWT_SECRET) {
  console.warn('WARNING: Using auto-generated JWT secret for development only');
  process.env.JWT_SECRET = crypto.randomBytes(64).toString('hex');
}

// Security-focused server setup
const PORT = process.env.PORT || 3000;

app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);

  // Security audit logging
  if (process.env.NODE_ENV === 'production') {
    console.log('Security middleware enabled');
  }
});

// Remove sensitive data from responses
app.use((req, res, next) => {
  // Remove any potential sensitive headers
  res.removeHeader('X-Powered-By');
  next();
});

// Security logging and monitoring
const morgan = require('morgan');

// Security-focused logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400, // Only log errors
  stream: process.stderr
}));

// Security event logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;

    // Log security-relevant events
    if (res.statusCode >= 400) {
      console.warn(`SECURITY: ${res.statusCode} ${req.method} ${req.url} - ${duration}ms`);
    }

    // Log potential attacks
    if (req.url.includes('../') || req.url.includes('..\\')) {
      console.error(`PATH_TRAVERSAL_ATTEMPT: ${req.ip} - ${req.url}`);
    }
  });

  next();
});

// Error handling that doesn't leak information
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);

  // Don't expose error details in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({ error: 'Internal server error' });
  } else {
    res.status(500).json({ 
      error: 'Internal server error',
      message: err.message 
    });
  }
});

