// Secure secrets loading and validation
const fs = require('fs');
const path = require('path');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.loadSecrets();
  }

  loadSecrets() {
    // Prefer environment variables over .env files
    this.loadFromEnv();

    // Validate all required secrets are present
    this.validateSecrets();
  }

  loadFromEnv() {
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    requiredSecrets.forEach(secret => {
      const value = process.env[secret];
      if (value) {
        this.secrets.set(secret, value);
      }
    });
  }

  validateSecrets() {
    const missingSecrets = [
      'DATABASE_URL',
      'JWT_SECRET'
    ].filter(secret => !this.secrets.has(secret));

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Validate secret formats
    this.validateSecretFormats();
  }

  validateSecretFormats() {
    // Example: Validate JWT secret length
    const jwtSecret = this.secrets.get('JWT_SECRET');
    if (jwtSecret && jwtSecret.length < 32) {
      console.warn('WARNING: JWT secret is too short (min 32 characters recommended)');
    }

    // Validate AWS key formats
    const awsKey = this.secrets.get('AWS_ACCESS_KEY_ID');
    if (awsKey && !awsKey.startsWith('AKIA')) {
      console.warn('WARNING: AWS access key format appears invalid');
    }
  }

  get(secretName) {
    const value = this.secrets.get(secretName);
    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }
    return value;
  }

  // Mask secrets for logging
  maskSecret(secretValue, visibleChars = 4) {
    if (!secretValue || secretValue.length <= visibleChars) {
      return '***';
    }
    return secretValue.slice(0, visibleChars) + '*'.repeat(secretValue.length - visibleChars);
  }
}

// Singleton instance
module.exports = new SecretsManager();

// Environment-specific configuration with fallbacks
const config = {
  // Development defaults (never use in production)
  development: {
    database: {
      url: process.env.DATABASE_URL || 'postgres://localhost:5432/dev',
      ssl: false
    },
    jwt: {
      secret: process.env.JWT_SECRET || 'dev-only-insecure-secret-change-in-production',
      expiresIn: '7d'
    }
  },

  // Production configuration (secrets must come from environment)
  production: {
    database: {
      url: () => {
        const url = process.env.DATABASE_URL;
        if (!url) {
          throw new Error('DATABASE_URL is required in production');
        }
        return url;
      },
      ssl: { rejectUnauthorized: true }
    },
    jwt: {
      secret: () => {
        const secret = process.env.JWT_SECRET;
        if (!secret || secret.length < 32) {
          throw new Error('Strong JWT_SECRET (min 32 chars) required in production');
        }
        return secret;
      },
      expiresIn: '1h'
    }
  },

  // Test configuration
  test: {
    database: {
      url: process.env.TEST_DATABASE_URL || 'postgres://localhost:5432/test',
      ssl: false
    },
    jwt: {
      secret: 'test-secret-for-verification-only',
      expiresIn: '1m'
    }
  }
};

// Get current environment configuration
const env = process.env.NODE_ENV || 'development';

// Environment validation
if (!['development', 'production', 'test'].includes(env)) {
  throw new Error(`Invalid NODE_ENV: ${env}. Must be development, production, or test`);
}

// Resolve configuration with environment-specific logic
const getConfig = () => {
  const envConfig = config[env];

  return {
    database: {
      url: typeof envConfig.database.url === 'function' 
        ? envConfig.database.url() 
        : envConfig.database.url,
      ssl: envConfig.database.ssl
    },
    jwt: {
      secret: typeof envConfig.jwt.secret === 'function'
        ? envConfig.jwt.secret()
        : envConfig.jwt.secret,
      expiresIn: envConfig.jwt.expiresIn
    },
    env: env
  };
};

module.exports = getConfig();

// Production-grade secrets management
const AWS = require('aws-sdk');

class ProductionSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTime = 5 * 60 * 1000; // 5 minutes cache
  }

  async getSecret(secretName, useCache = true) {
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTime) {
        return cached.value;
      }
    }

    // Use AWS Secrets Manager (preferred)
    if (process.env.AWS_REGION) {
      return await this.getFromAwsSecretsManager(secretName);
    }

    // Fallback to environment variables
    const envValue = process.env[secretName];
    if (!envValue) {
      throw new Error(`Secret ${secretName} not found in environment`);
    }

    this.cache.set(secretName, {
      value: envValue,
      timestamp: Date.now()
    });

    return envValue;
  }

  async getFromAwsSecretsManager(secretName) {
    try {
      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION
      });

      const response = await client.getSecretValue({
        SecretId: secretName
      }).promise();

      let secretValue;
      if ('SecretString' in response) {
        secretValue = response.SecretString;
      } else {
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName} from AWS:`, error.message);

      // Fallback to environment variable
      const fallback = process.env[secretName];
      if (fallback) {
        console.warn(`Using fallback environment variable for ${secretName}`);
        return fallback;
      }

      throw new Error(`Secret ${secretName} not available`);
    }
  }

  // Rotate secrets (for定期 rotation)
  async rotateSecret(secretName) {
    this.cache.delete(secretName);
    return await this.getSecret(secretName, false);
  }

  // Security: Clear cache
  clearCache() {
    this.cache.clear();
  }
}

// Singleton with error handling
let secretsManager;

try {
  secretsManager = new ProductionSecretsManager();
} catch (error) {
  console.error('Failed to initialize secrets manager:', error.message);
  // Continue with basic environment variables for resilience
}

module.exports = secretsManager || {
  getSecret: async (secretName) => {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret ${secretName} not found`);
    }
    return value;
  }
};

