const Joi = require('joi');

// Environment validation schema
const envVarsSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),

  PORT: Joi.number().default(3000),

  // Security
  JWT_SECRET: Joi.string().required()
    .description('JWT secret key'),
  SESSION_SECRET: Joi.string().required()
    .description('Session secret'),

  // CORS
  ALLOWED_ORIGINS: Joi.string().default('http://localhost:3000,http://localhost:3001'),

  // Database (if used)
  DATABASE_URL: Joi.string().uri().optional(),

  // API Keys (validate format if used)
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),
  LOGFIRE_TOKEN: Joi.string().optional()
})
.unknown(); // Allow unknown environment variables

const { value: envVars, error } = envVarsSchema.validate(process.env);

if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

const config = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,

  // Security
  jwtSecret: envVars.JWT_SECRET,
  sessionSecret: envVars.SESSION_SECRET,

  // CORS
  allowedOrigins: envVars.ALLOWED_ORIGINS.split(','),

  // Database
  databaseUrl: envVars.DATABASE_URL,

  // API Keys
  awsAccessKeyId: envVars.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: envVars.AWS_SECRET_ACCESS_KEY,
  anthropicApiKey: envVars.ANTHROPIC_API_KEY,
  stripeSecretKey: envVars.STRIPE_SECRET_KEY,
  logfireToken: envVars.LOGFIRE_TOKEN
};

// Validate required secrets for production
if (config.env === 'production') {
  const requiredSecrets = [
    'jwtSecret',
    'sessionSecret'
  ];

  const missingSecrets = requiredSecrets.filter(secret => !config[secret]);

  if (missingSecrets.length > 0) {
    throw new Error(`Missing required secrets in production: ${missingSecrets.join(', ')}`);
  }
}

module.exports = config;

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if ('SecretString' in response) {
        secretValue = response.SecretString;
      } else {
        const buff = Buffer.from(response.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Parse JSON if it's a JSON string
      try {
        secretValue = JSON.parse(secretValue);
      } catch (e) {
        // Not JSON, keep as string
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

const envConfig = require('./env');
const secretsManager = require('./secrets');

class Config {
  constructor() {
    this.config = { ...envConfig };
    this.secretNames = {
      DATABASE: process.env.DATABASE_SECRET_NAME || 'app/database',
      API_KEYS: process.env.API_KEYS_SECRET_NAME || 'app/api-keys',
      JWT: process.env.JWT_SECRET_NAME || 'app/jwt'
    };
  }

  async initialize() {
    // Load secrets from AWS Secrets Manager if in production
    if (this.config.env === 'production') {
      try {
        await this.loadProductionSecrets();
      } catch (error) {
        console.error('Failed to load production secrets:', error);
        // In production, we should fail fast if secrets can't be loaded
        if (process.env.NODE_ENV === 'production') {
          process.exit(1);
        }
      }
    }

    return this.config;
  }

  async loadProductionSecrets() {
    try {
      // Load database credentials
      if (!this.config.databaseUrl) {
        const dbSecret = await secretsManager.getSecret(this.secretNames.DATABASE);
        this.config.databaseUrl = dbSecret.connectionString || dbSecret;
      }

      // Load API keys
      const apiKeys = await secretsManager.getSecret(this.secretNames.API_KEYS);
      this.config.awsAccessKeyId = apiKeys.awsAccessKeyId || this.config.awsAccessKeyId;
      this.config.awsSecretAccessKey = apiKeys.awsSecretAccessKey || this.config.awsSecretAccessKey;
      this.config.anthropicApiKey = apiKeys.anthropicApiKey || this.config.anthropicApiKey;
      this.config.stripeSecretKey = apiKeys.stripeSecretKey || this.config.stripeSecretKey;
      this.config.logfireToken = apiKeys.logfireToken || this.config.logfireToken;

      // Load JWT secret if not in env
      if (!this.config.jwtSecret) {
        const jwtSecret = await secretsManager.getSecret(this.secretNames.JWT);
        this.config.jwtSecret = jwtSecret;
      }

    } catch (error) {
      console.warn('Could not load secrets from AWS Secrets Manager, using environment variables:', error.message);
    }
  }

  getConfig() {
    return this.config;
  }

  // Helper to get specific config values
  get(key) {
    return this.config[key];
  }
}

// Create and initialize config
const configInstance = new Config();

// For immediate use, we'll initialize synchronously for dev, async for prod
if (process.env.NODE_ENV === 'production') {
  configInstance.initialize().catch(console.error);
}

module.exports = configInstance;

