// Secure secrets management with fallback to environment variables
// Prefer cloud secrets manager in production

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.useCloudSecrets = process.env.NODE_ENV === 'production' && 
                          process.env.AWS_REGION &&
                          process.env.AWS_ACCESS_KEY_ID &&
                          process.env.AWS_SECRET_ACCESS_KEY;

    if (this.useCloudSecrets) {
      this.client = new SecretsManagerClient({
        region: process.env.AWS_REGION,
      });
    }
  }

  async getSecret(secretName, defaultValue = null) {
    // Check cache first
    if (this.secrets.has(secretName)) {
      return this.secrets.get(secretName);
    }

    // Try environment variable
    const envValue = process.env[secretName];
    if (envValue) {
      this.secrets.set(secretName, envValue);
      return envValue;
    }

    // Try AWS Secrets Manager in production
    if (this.useCloudSecrets) {
      try {
        const response = await this.client.send(
          new GetSecretValueCommand({ SecretId: secretName })
        );
        const secretValue = response.SecretString;
        this.secrets.set(secretName, secretValue);
        return secretValue;
      } catch (error) {
        console.warn(`Failed to fetch secret ${secretName} from AWS:`, error.message);
      }
    }

    // Fallback to default value
    if (defaultValue !== null) {
      console.warn(`Using default value for secret: ${secretName}`);
      return defaultValue;
    }

    throw new Error(`Secret ${secretName} not found and no default provided`);
  }

  // For testing purposes - allows mocking secrets
  setSecret(secretName, value) {
    this.secrets.set(secretName, value);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

#!/usr/bin/env node
// Environment validation script - run this before starting the app

const requiredEnvVars = [
  'NODE_ENV',
  'PORT'
];

const requiredSecrets = {
  development: ['JWT_SECRET'],
  production: [
    'JWT_SECRET',
    'DATABASE_URL'
  ],
  test: [] // Test environment can use defaults
};

function validateEnvironment() {
  const env = process.env.NODE_ENV || 'development';
  const missingVars = [];
  const warnings = [];

  // Check required environment variables
  for (const envVar of requiredEnvVars) {
    if (!process.env[envVar]) {
      missingVars.push(envVar);
    }
  }

  // Check required secrets for current environment
  const secrets = requiredSecrets[env] || [];
  for (const secret of secrets) {
    if (!process.env[secret]) {
      missingVars.push(secret);
    }
  }

  // Check for default/fallback values in production
  if (env === 'production') {
    if (process.env.JWT_SECRET && process.env.JWT_SECRET.includes('fallback')) {
      warnings.push('JWT_SECRET appears to be using fallback value in production');
    }

    if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('localhost')) {
      warnings.push('DATABASE_URL appears to be using localhost in production');
    }
  }

  // Check for test credentials in non-test environments
  if (env !== 'test') {
    const testPatterns = [
      /CANARY/,
      /test_/,
      /example\.com/,
      /localhost/
    ];

    Object.keys(process.env).forEach(key => {
      const value = process.env[key];
      testPatterns.forEach(pattern => {
        if (pattern.test(value)) {
          warnings.push(`Environment variable ${key} contains test pattern: ${value}`);
        }
      });
    });
  }

  if (missingVars.length > 0) {
    console.error('❌ Missing required environment variables:');
    missingVars.forEach(varName => console.error(`  - ${varName}`));
    process.exit(1);
  }

  if (warnings.length > 0) {
    console.warn('⚠️  Environment warnings:');
    warnings.forEach(warning => console.warn(`  - ${warning}`));
  }

  console.log('✅ Environment validation successful');
  return true;
}

if (require.main === module) {
  validateEnvironment();
}

module.exports = validateEnvironment;

