// Secure app with proper secrets management
require('dotenv').config();

const express = require('express');
const { securityHeaders, limiter, validateInput } = require('./security-middleware');
const { authenticateToken, authorize } = require('./auth-middleware');
const secretsManager = require('./config/secrets');

const app = express();
app.use(express.json());

// Security middleware
app.use(securityHeaders);
app.use(limiter);
app.use(validateInput);

// Initialize secrets
async function initializeSecrets() {
  try {
    // Pre-load critical secrets
    const jwtSecret = await secretsManager.getSecret(
      'JWT_SECRET', 
      process.env.NODE_ENV === 'production' ? null : 'fallback-dev-secret-change-in-prod'
    );

    console.log('✅ Secrets initialized successfully');
    return { jwtSecret };
  } catch (error) {
    console.error('❌ Failed to initialize secrets:', error.message);
    if (process.env.NODE_ENV === 'production') {
      process.exit(1); // Don't start in production without secrets
    }
    return { jwtSecret: 'fallback-secret-for-development' };
  }
}

// Public endpoints
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    secrets: process.env.NODE_ENV === 'development' ? 'using-secure-manager' : 'secured'
  });
});

// Authenticated endpoints (secrets-aware)
app.get('/users', authenticateToken, authorize(['admin', 'user']), async (req, res) => {
  try {
    // Example: Get database URL from secrets manager if needed
    const dbUrl = await secretsManager.getSecret('DATABASE_URL', null);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: req.user.role === 'admin' || req.user.id === user.id ? user.email : undefined
    }));

    res.json({
      users: sanitizedUsers,
      // Only show secret info in development for debugging
      _meta: process.env.NODE_ENV === 'development' ? { 
        secretsManager: 'active',
        hasDbSecret: !!dbUrl 
      } : undefined
    });
  } catch (error) {
    console.error('Error in users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint with secure secret usage
app.post('/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password required' });
    }

    // Get JWT secret securely
    const jwtSecret = await secretsManager.getSecret('JWT_SECRET');

    // Simplified authentication - in real app, use database with hashed passwords
    if (username === 'admin' && password === 'securepassword') {
      const token = require('jsonwebtoken').sign(
        { id: 1, username: 'admin', role: 'admin' },
        jwtSecret,
        { expiresIn: '1h' }
      );

      return res.json({ 
        token,
        message: 'Login successful' 
      });
    }

    res.status(401).json({ error: 'Invalid credentials' });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Authentication service unavailable' });
  }
});

// Error handling
app.use((err, req, res, next) => {
  console.error('Application error:', err.stack);

  // Don't leak secret information in error responses
  const errorResponse = {
    error: 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { 
      details: err.message 
    })
  };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// Start server with secrets initialization
async function startServer() {
  try {
    await initializeSecrets();

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`🚀 Secure server running on port ${PORT}`);
      console.log(`📁 Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`🔐 Secrets management: ${secretsManager.useCloudSecrets ? 'AWS Secrets Manager' : 'Environment variables'}`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

startServer();

module.exports = app;

