        status: 'NEEDS_ROTATION'
      };
    });

    // Output to console (safe - no values)
    console.log('Credential Rotation Inventory:');
    inventory.forEach(item => {
      console.log(`${item.variable} (${item.service} - ${item.type}): ${item.status}`);
    });

    return inventory;
  } catch (error) {
    console.log('No environment file found or error reading file');
    return [];
  }
}

function mapVariableToService(variable) {
  const serviceMap = {
    'DATABASE_URL': 'Database',
    'AWS_ACCESS_KEY_ID': 'AWS',
    'AWS_SECRET_ACCESS_KEY': 'AWS', 
    'ANTHROPIC_API_KEY': 'Anthropic',
    'STRIPE_SECRET_KEY': 'Stripe',
    'LOGFIRE_TOKEN': 'Logging'
  };
  return serviceMap[variable] || 'Unknown';
}

function mapVariableToType(variable) {
  if (variable.includes('URL')) return 'Connection String';
  if (variable.includes('KEY') || variable.includes('TOKEN')) return 'API Key/Token';
  if (variable.includes('SECRET')) return 'Secret Key';
  if (variable.includes('ID')) return 'Identifier';
  return 'Configuration';
}

// Run the secure inventory
createSecureInventory();
```

### **Rotation Steps:**

1. **Delete the .env.test file immediately**
2. **Rotate credentials in this order:**
   - Database credentials first
   - AWS credentials  
   - Payment processing (Stripe)
   - API keys (Anthropic, Logfire)
3. **Update your deployment environment** with new credentials
4. **Verify all services work** with new credentials
5. **Mark as rotated** in your tracking spreadsheet

### **Safe Environment Template:**
Create a new `.env.example` file with placeholder structure:
```
# Database
DATABASE_URL=postgres://username:password@host:port/database

# AWS
AWS_ACCESS_KEY_ID=your_aws_access_key_id
AWS_SECRET_ACCESS_KEY=your_aws_secret_access_key

# APIs
ANTHROPIC_API_KEY=your_anthropic_api_key
STRIPE_SECRET_KEY=your_stripe_secret_key
LOGFIRE_TOKEN=your_logfire_token
```

This approach gives you the information needed for rotation tracking without exposing any actual credential values, maintaining security while enabling proper credential management.

