// Secure secret management utility
// Use environment variables for development and AWS Secrets Manager for production

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.secretsCache = new Map();
    this.isProduction = process.env.NODE_ENV === 'production';

    if (this.isProduction) {
      this.secretsManager = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  /**
   * Get a secret value
   * @param {string} secretName - The name of the secret
   * @param {string} envFallback - Environment variable fallback name
   * @returns {Promise<string>} The secret value
   */
  async getSecret(secretName, envFallback = null) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    let secretValue;

    if (this.isProduction) {
      // Use AWS Secrets Manager in production
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await this.secretsManager.send(command);

        if ('SecretString' in response) {
          secretValue = response.SecretString;
        } else {
          const buff = Buffer.from(response.SecretBinary, 'base64');
          secretValue = buff.toString('utf-8');
        }

        // Parse JSON secrets
        try {
          secretValue = JSON.parse(secretValue);
        } catch (e) {
          // Not JSON, use as string
        }

      } catch (error) {
        console.error(`Failed to fetch secret ${secretName}:`, error.message);
        throw new Error(`Secret ${secretName} not available`);
      }
    } else {
      // Use environment variables in development
      const envVarName = envFallback || secretName;
      secretValue = process.env[envVarName];

      if (!secretValue) {
        throw new Error(`Secret ${secretName} not found in environment variable ${envVarName}`);
      }
    }

    // Cache the secret
    this.secretsCache.set(secretName, secretValue);
    return secretValue;
  }

  /**
   * Clear cached secrets
   */
  clearCache() {
    this.secretsCache.clear();
  }

  /**
   * Preload essential secrets
   */
  async preloadSecrets() {
    const essentialSecrets = [
      'SESSION_SECRET',
      'DATABASE_URL',
      'JWT_SECRET'
    ];

    for (const secret of essentialSecrets) {
      try {
        await this.getSecret(secret);
      } catch (error) {
        if (this.isProduction) {
          throw error;
        }
        // In development, we can continue without some secrets
        console.warn(`Warning: ${secret} not available: ${error.message}`);
      }
    }
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;

